-- 10. 2~3단계 적용 전 점검 (조회 전용, 데이터·설정 변경 없음)
-- 결과 표 전체를 캡처해 보내 주세요. ok 가 false 인 행이 있으면 적용하지 않습니다.
-- 1~10행: 현재 운영(090000·093000·095000) 상태, 11~20행: 091000·094000·096000 흔적 없음, 21~24행: 마이그레이션 요건.
-- 데이터 행은 개수만 세며 내용을 읽지 않습니다.
SELECT no, item, actual, expected,
       CASE WHEN expected = '기록용' THEN NULL ELSE actual IS NOT DISTINCT FROM expected END AS ok
FROM (VALUES
    (1, '[090000] 감사 트리거 부착 일지 테이블', (SELECT count(*)::text FROM pg_trigger WHERE tgname = 'trg_audit_row_change' AND tgrelid = ANY (ARRAY(SELECT to_regclass('public.' || t)::oid FROM unnest(ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs', 'daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) t)) AND tgenabled <> 'D'), '25'),
    (2, '[090000] audit_logs 추가 전용·해시 체인 트리거', (SELECT count(*)::text FROM pg_trigger WHERE tgrelid = 'public.audit_logs'::regclass AND tgname IN ('trg_audit_logs_chain_hash','trg_audit_logs_append_only','trg_audit_logs_no_truncate')), '3'),
    (3, '[090000] data_corrections 테이블', (to_regclass('public.data_corrections') IS NOT NULL)::text, 'true'),
    (4, '[090000] data_corrections 추가 전용 트리거', (SELECT count(*)::text FROM pg_trigger WHERE tgrelid = to_regclass('public.data_corrections') AND tgname IN ('trg_data_corrections_append_only','trg_data_corrections_no_truncate')), '2'),
    (5, '[093000] audit_logs 로그인 사용자 INSERT 권한(없어야 함)', has_table_privilege('authenticated', 'public.audit_logs', 'INSERT')::text, 'false'),
    (6, '[095000] 일지 회사 범위 정책', (SELECT count(*)::text FROM pg_policies WHERE schemaname = 'public' AND tablename = ANY (ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs', 'daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) AND policyname = tablename || '_org_access'), '25'),
    (7, '[095000] 일지 전체 정책 수', (SELECT count(*)::text FROM pg_policies WHERE schemaname = 'public' AND tablename = ANY (ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs', 'daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[])), '25'),
    (8, '[095000] anon 일지 조회 권한(없어야 함)', has_table_privilege('anon', 'public.daily_hygiene_logs', 'SELECT')::text, 'false'),
    (9, '[095000] daily_log_org_codes 함수', (to_regprocedure('public.daily_log_org_codes()') IS NOT NULL)::text, 'true'),
    (10, '필요 함수 is_admin_like / get_my_organization_code', ((to_regprocedure('public.is_admin_like()') IS NOT NULL)::text || '/' || (to_regprocedure('public.get_my_organization_code()') IS NOT NULL)::text), 'true/true'),
    (11, '[091000 전] 승인시각 보호 트리거(없어야 함)', (SELECT count(*)::text FROM pg_trigger WHERE tgname = 'trg_daily_log_approval_times' AND tgrelid = ANY (ARRAY(SELECT to_regclass('public.' || t)::oid FROM unnest(ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs']::text[]) t)) AND tgenabled <> 'D'), '0'),
    (12, '[091000 전] 정정 허용 확인 함수(없어야 함)', (to_regprocedure('public.daily_log_correction_allows(text, uuid)') IS NOT NULL)::text, 'false'),
    (13, '[091000 전] 승인시각 보호 함수(없어야 함)', (to_regprocedure('public.enforce_daily_log_approval_times()') IS NOT NULL)::text, 'false'),
    (14, '[094000 전] 항목 잠금 트리거(없어야 함)', (SELECT count(*)::text FROM pg_trigger WHERE tgname = 'trg_daily_log_item_parent_unlocked' AND tgrelid = ANY (ARRAY(SELECT to_regclass('public.' || t)::oid FROM unnest(ARRAY['daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) t)) AND tgenabled <> 'D'), '0'),
    (15, '[094000 전] 정정 요청 함수(없어야 함)', (to_regprocedure('public.request_daily_log_correction(text, uuid, text)') IS NOT NULL)::text, 'false'),
    (16, '[094000 전] data_corrections.kind 컬럼(없어야 함)', (EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'data_corrections' AND column_name = 'kind'))::text, 'false'),
    (17, '[094000 전] data_corrections.requested_by 컬럼(없어야 함)', (EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'data_corrections' AND column_name = 'requested_by'))::text, 'false'),
    (18, '[096000 전] 작성자 권한 트리거(머리글, 없어야 함)', (SELECT count(*)::text FROM pg_trigger WHERE tgname = 'trg_daily_log_edit_rights' AND tgrelid = ANY (ARRAY(SELECT to_regclass('public.' || t)::oid FROM unnest(ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs']::text[]) t)) AND tgenabled <> 'D'), '0'),
    (19, '[096000 전] 작성자 권한 트리거(항목, 없어야 함)', (SELECT count(*)::text FROM pg_trigger WHERE tgname = 'trg_daily_log_item_edit_rights' AND tgrelid = ANY (ARRAY(SELECT to_regclass('public.' || t)::oid FROM unnest(ARRAY['daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) t)) AND tgenabled <> 'D'), '0'),
    (20, '[096000 전] 조도 일지 author_user_id 컬럼(없어야 함)', (EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'daily_illumination_logs' AND column_name = 'author_user_id'))::text, 'false'),
    (21, '[091000 요건] 머리글 13종 필수 컬럼 누락 수', (SELECT count(*)::text FROM unnest(ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs']::text[]) t CROSS JOIN unnest(ARRAY['id','status','created_at','submitted_at','approved_at','approved_by','approved_by_name','rejected_at','rejected_by']) c WHERE NOT EXISTS (SELECT 1 FROM information_schema.columns x WHERE x.table_schema = 'public' AND x.table_name = t AND x.column_name = c)), '0'),
    (22, '[094000 요건] 항목 12종 log_id 컬럼', (SELECT count(*)::text FROM information_schema.columns WHERE table_schema = 'public' AND table_name = ANY (ARRAY['daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) AND column_name = 'log_id'), '12'),
    (23, '[096000 요건] author_user_id 있는 머리글(조도 제외 12)', (SELECT count(*)::text FROM information_schema.columns WHERE table_schema = 'public' AND table_name = ANY (ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs']::text[]) AND column_name = 'author_user_id'), '12'),
    (24, '[096000 요건] submitted_by 있는 머리글', (SELECT count(*)::text FROM information_schema.columns WHERE table_schema = 'public' AND table_name = ANY (ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs']::text[]) AND column_name = 'submitted_by'), '13'),
    (25, 'RLS 강제(FORCE) 걸린 일지 테이블(정정 함수 동작 조건)', (SELECT count(*)::text FROM pg_class WHERE oid = ANY (ARRAY(SELECT to_regclass('public.' || t)::oid FROM unnest(ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs', 'daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) t)) AND relforcerowsecurity), '0'),
    (26, '일지 테이블의 기타 트리거(기록용)', (SELECT COALESCE(string_agg(DISTINCT tgname, ', ' ORDER BY tgname), '없음') FROM pg_trigger WHERE NOT tgisinternal AND tgrelid = ANY (ARRAY(SELECT to_regclass('public.' || t)::oid FROM unnest(ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs', 'daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) t)) AND tgname <> 'trg_audit_row_change'), '기록용'),
    (27, 'data_corrections 행 수(기록용)', (SELECT count(*)::text FROM public.data_corrections), '기록용'),
    (28, 'SQL Editor 실행 역할 / RLS 우회 / 일지 테이블 소유자(기록용)', (SELECT current_user || ' / ' || rolbypassrls::text || ' / ' || (SELECT pg_get_userbyid(relowner) FROM pg_class WHERE oid = 'public.daily_hygiene_logs'::regclass) FROM pg_roles WHERE rolname = current_user), '기록용')
) AS v(no, item, actual, expected)
ORDER BY no;
